/* 2mm.c: this file is part of PolyBench/C */

#include <stdio.h>
#include <unistd.h>
#include <string.h>
#include <math.h>

/* Include polybench common header. */
#include <polybench.h>

/* Include benchmark-specific header. */
#include "2mm.h"


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("D");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, D[i][j]);
    }
  POLYBENCH_DUMP_END("D");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_2mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k;

  /* Create local restrict-qualified views to help the compiler
     reason about aliasing and enable more aggressive vectorization. */
  DATA_TYPE (*restrict A_)[nk]  = A;
  DATA_TYPE (*restrict B_)[nj]  = B;
  DATA_TYPE (*restrict C_)[nl]  = C;
  DATA_TYPE (*restrict tmp_)[nj]= tmp;
  DATA_TYPE (*restrict D_)[nl]  = D;

  /* Cache/blocking parameters.
     These are chosen so that the working tiles of A/B/tmp and tmp/C/D
     for each phase fit comfortably into L2 cache on a modern x64 CPU. */
  const int Ti = 64; /* tile size in i (rows)    */
  const int Tj = 64; /* tile size in j (NJ dim)  */
  const int Tk = 64; /* tile size in k (NK dim)  */
  const int Tl = 64; /* tile size in l (NL dim)  */

#pragma scop
  /* ------------------------------------------------------------------
   * Phase 1: tmp = alpha * A * B
   *
   * Original:
   *   for i
   *     for j
   *       tmp[i][j] = 0;
   *       for k
   *         tmp[i][j] += alpha * A[i][k] * B[k][j];
   *
   * Optimized:
   *   - Initialize tmp row blocks once per (i, j) before accumulation.
   *   - Use loop order i / k / j so that j (the innermost loop) walks
   *     contiguous memory in both tmp[i][j] and B[k][j].
   *   - Tile i, j, k to keep working sets in cache.
   * ------------------------------------------------------------------ */
  {
    int ii, jj, kk;

    for (ii = 0; ii < _PB_NI; ii += Ti) {
      int i_end = ii + Ti;
      if (i_end > _PB_NI)
        i_end = _PB_NI;

      /* Initialize tmp for rows in this i-tile. */
      for (i = ii; i < i_end; ++i) {
        for (j = 0; j < _PB_NJ; ++j) {
          tmp_[i][j] = SCALAR_VAL(0.0);
        }
      }

      /* Blocked matrix multiplication for this i-tile. */
      for (kk = 0; kk < _PB_NK; kk += Tk) {
        int k_end = kk + Tk;
        if (k_end > _PB_NK)
          k_end = _PB_NK;

        for (jj = 0; jj < _PB_NJ; jj += Tj) {
          int j_end = jj + Tj;
          if (j_end > _PB_NJ)
            j_end = _PB_NJ;

          for (i = ii; i < i_end; ++i) {
            for (k = kk; k < k_end; ++k) {
              DATA_TYPE a_ik = alpha * A_[i][k];
              /* Pointers to contiguous slices used in the innermost loop. */
              DATA_TYPE       *restrict tmp_row = &tmp_[i][jj];
              const DATA_TYPE *restrict B_row   = &B_[k][jj];

              /* Innermost loop over contiguous j dimension.
                 Both tmp_row[j_local] and B_row[j_local] are stride-1. */
              for (j = 0; j < j_end - jj; ++j) {
                tmp_row[j] += a_ik * B_row[j];
              }
            }
          }
        }
      }
    }
  }

  /* ------------------------------------------------------------------
   * Phase 2: D = beta * D + tmp * C
   *
   * Original:
   *   for i
   *     for l (named j in original code)
   *       D[i][l] *= beta;
   *       for j (0..NJ-1)
   *         D[i][l] += tmp[i][j] * C[j][l];
   *
   * Optimized:
   *   - Loop order: i / j / l, with l innermost, so that D[i][l] and
   *     C[j][l] are accessed with unit stride.
   *   - Tile i, j (NJ-dim) and l (NL-dim) to improve cache reuse of
   *     tmp rows and C rows and of tiles of D.
   *   - Scaling by beta is performed once per D element, immediately
   *     before accumulating all contributions from tmp * C for that
   *     element (within its D-tile).
   * ------------------------------------------------------------------ */
  {
    int ii, jj, ll;

    for (ii = 0; ii < _PB_NI; ii += Ti) {
      int i_end = ii + Ti;
      if (i_end > _PB_NI)
        i_end = _PB_NI;

      for (ll = 0; ll < _PB_NL; ll += Tl) {
        int l_end = ll + Tl;
        if (l_end > _PB_NL)
          l_end = _PB_NL;

        /* Scale the current D-tile by beta. */
        for (i = ii; i < i_end; ++i) {
          DATA_TYPE *restrict D_row = &D_[i][ll];
          for (j = 0; j < l_end - ll; ++j) {
            D_row[j] *= beta;
          }
        }

        /* Accumulate tmp * C into the same D-tile. */
        for (jj = 0; jj < _PB_NJ; jj += Tj) {
          int j_end = jj + Tj;
          if (j_end > _PB_NJ)
            j_end = _PB_NJ;

          for (i = ii; i < i_end; ++i) {
            DATA_TYPE *restrict D_row = &D_[i][ll];

            for (k = jj; k < j_end; ++k) {
              DATA_TYPE t_ik = tmp_[i][k];
              const DATA_TYPE *restrict C_row = &C_[k][ll];

              /* Innermost loop over contiguous l dimension.
                 D_row[l_local] and C_row[l_local] are stride-1. */
              for (j = 0; j < l_end - ll; ++j) {
                D_row[j] += t_ik * C_row[j];
              }
            }
          }
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(tmp,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NJ,NL,nj,nl);
  POLYBENCH_2D_ARRAY_DECL(D,DATA_TYPE,NI,NL,ni,nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_2mm (ni, nj, nk, nl,
	      alpha, beta,
	      POLYBENCH_ARRAY(tmp),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(D)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);

  return 0;
}
