/* Include benchmark-specific header. */
#include "2mm.h"

/* -------------------------------------------------------------------------
 * Tunable blocking parameters.
 *
 * These control the row/column block sizes used inside the kernel to
 * improve cache locality. They can be overridden at compile time using
 * -DT2MM_I_BLOCK=... etc., but reasonable defaults are provided.
 * ------------------------------------------------------------------------- */
#ifndef T2MM_I_BLOCK
# define T2MM_I_BLOCK 64
#endif

#ifndef T2MM_L_BLOCK
# define T2MM_L_BLOCK 64
#endif


/* Array initialization. */
static
void init_array(int ni, int nj, int nk, int nl,
		DATA_TYPE *alpha,
		DATA_TYPE *beta,
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  *alpha = 1.5;
  *beta = 1.2;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nk; j++)
      A[i][j] = (DATA_TYPE) ((i*j+1) % ni) / ni;
  for (i = 0; i < nk; i++)
    for (j = 0; j < nj; j++)
      B[i][j] = (DATA_TYPE) (i*(j+1) % nj) / nj;
  for (i = 0; i < nj; i++)
    for (j = 0; j < nl; j++)
      C[i][j] = (DATA_TYPE) ((i*(j+3)+1) % nl) / nl;
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++)
      D[i][j] = (DATA_TYPE) (i*(j+2) % nk) / nk;
}


/* DCE code. Must scan the entire live-out data.
   Can be used also to check the correctness of the output. */
static
void print_array(int ni, int nl,
		 DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j;

  POLYBENCH_DUMP_START;
  POLYBENCH_DUMP_BEGIN("D");
  for (i = 0; i < ni; i++)
    for (j = 0; j < nl; j++) {
	if ((i * ni + j) % 20 == 0) fprintf (POLYBENCH_DUMP_TARGET, "\n");
	fprintf (POLYBENCH_DUMP_TARGET, DATA_PRINTF_MODIFIER, D[i][j]);
    }
  POLYBENCH_DUMP_END("D");
  POLYBENCH_DUMP_FINISH;
}


/* Main computational kernel. The whole function will be timed,
   including the call and return.

   Optimizations compared to the baseline version:
     - Loop reordering to give unit‑stride access in the innermost loop:
         * For tmp = alpha * A * B: iterate (i, k, j) so j is innermost.
         * For D = beta * D + tmp * C: iterate (i, j, l) so l is innermost.
       This matches row-major storage and enables efficient vectorization.
     - Simple blocking on the i (row) and l (column) dimensions so that
       row blocks of tmp/D stay in cache while they are produced/consumed.
     - Scalar hoisting:
         * a_ik = alpha * A[i][k] is computed once per (i, k).
         * t_ij = tmp[i][j] is computed once per (i, j).
     - Use of local pointer aliases (marked restrict) to help the compiler
       reason about aliasing and generate better code.

   Mathematically, the kernel still computes:
       tmp = alpha * A * B
       D   = beta * D + tmp * C
     i.e.,
       D = alpha * A * B * C + beta * D
*/
static
void kernel_2mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  /* Local copies of problem sizes (the _PB_* macros may be expressions). */
  const int ni_ = _PB_NI;
  const int nj_ = _PB_NJ;
  const int nk_ = _PB_NK;
  const int nl_ = _PB_NL;

  /* Local aliases with explicit row-major layout and restrict qualifiers.
     This makes the aliasing and indexing model clear for the optimizer. */
  DATA_TYPE (* __restrict__ tmp_)[NJ] = tmp;
  DATA_TYPE (* __restrict__ A_)[NK]   = A;
  DATA_TYPE (* __restrict__ B_)[NJ]   = B;
  DATA_TYPE (* __restrict__ C_)[NL]   = C;
  DATA_TYPE (* __restrict__ D_)[NL]   = D;

  const DATA_TYPE alpha_ = alpha;
  const DATA_TYPE beta_  = beta;

  /* Blocking factors for rows (i) and columns of D/C (l). */
  const int Ti = T2MM_I_BLOCK;
  const int Tl = T2MM_L_BLOCK;

#pragma scop
  /* -----------------------------------------------------------------------
   * Stage 1: tmp = alpha * A * B
   *
   * Original:
   *   for i
   *     for j
   *       tmp[i][j] = 0;
   *       for k
   *         tmp[i][j] += alpha * A[i][k] * B[k][j];
   *
   * Reordered to i–k–j with an explicit zeroing pass per row block:
   *   - j is the innermost loop, so B[k][j] and tmp[i][j] are accessed
   *     with unit stride (row-major layout).
   *   - alpha * A[i][k] is hoisted outside the j-loop.
   *   - Rows are processed in tiles [ii, i_end) to keep working sets small.
   * ----------------------------------------------------------------------- */
  for (int ii = 0; ii < ni_; ii += Ti)
  {
    const int i_end = (ii + Ti < ni_) ? (ii + Ti) : ni_;

    /* Initialize tmp block for rows [ii, i_end) across all columns j. */
    for (int i = ii; i < i_end; ++i)
    {
      DATA_TYPE * __restrict__ tmp_row = tmp_[i];
      for (int j = 0; j < nj_; ++j)
        tmp_row[j] = SCALAR_VAL(0.0);
    }

    /* Accumulate alpha * A * B into tmp for the current row block. */
    for (int k = 0; k < nk_; ++k)
    {
      const DATA_TYPE * __restrict__ B_row = B_[k];  /* B[k][*] */
      for (int i = ii; i < i_end; ++i)
      {
        const DATA_TYPE a_ik = alpha_ * A_[i][k];
        DATA_TYPE * __restrict__ tmp_row = tmp_[i];

        /* Innermost loop: contiguous in j for both tmp_row and B_row. */
        for (int j = 0; j < nj_; ++j)
          tmp_row[j] += a_ik * B_row[j];
      }
    }
  }

  /* -----------------------------------------------------------------------
   * Stage 2: D = beta * D + tmp * C
   *
   * Original:
   *   for i
   *     for l
   *       D[i][l] *= beta;
   *       for j
   *         D[i][l] += tmp[i][j] * C[j][l];
   *
   * Reordered to i–j–l, still computing for each (i,l):
   *   D[i][l] = beta * D[i][l] + sum_j tmp[i][j] * C[j][l].
   *
   * Implementation strategy:
   *   - Process rows in the same tiles [ii, i_end) as Stage 1.
   *   - Within each row tile, also block the l dimension to work on
   *     column panels [ll, l_end) of D and C that fit into cache.
   *   - First, scale the D tile by beta.
   *   - Then, for each j, load tmp[i][j] once (t_ij) and update the
   *     corresponding D-row slice with a unit-stride loop over l.
   * ----------------------------------------------------------------------- */
  for (int ii = 0; ii < ni_; ii += Ti)
  {
    const int i_end = (ii + Ti < ni_) ? (ii + Ti) : ni_;

    for (int ll = 0; ll < nl_; ll += Tl)
    {
      const int l_end = (ll + Tl < nl_) ? (ll + Tl) : nl_;
      const int tile_len_l = l_end - ll;

      /* Scale D tile by beta: D[i][l] *= beta for
         i in [ii, i_end), l in [ll, l_end). */
      for (int i = ii; i < i_end; ++i)
      {
        DATA_TYPE * __restrict__ D_row = D_[i] + ll;
        for (int off = 0; off < tile_len_l; ++off)
          D_row[off] *= beta_;
      }

      /* Add tmp * C into the same D tile:
           D[i][l] += tmp[i][j] * C[j][l]
         for all j, i in [ii, i_end), l in [ll, l_end). */
      for (int j = 0; j < nj_; ++j)
      {
        const DATA_TYPE * __restrict__ C_row = C_[j] + ll;  /* C[j][ll..l_end) */

        for (int i = ii; i < i_end; ++i)
        {
          const DATA_TYPE t_ij = tmp_[i][j];
          DATA_TYPE * __restrict__ D_row = D_[i] + ll;

          /* Innermost loop over contiguous l-range. */
          for (int off = 0; off < tile_len_l; ++off)
            D_row[off] += t_ij * C_row[off];
        }
      }
    }
  }
#pragma endscop
}


int main(int argc, char** argv)
{
  /* Retrieve problem size. */
  int ni = NI;
  int nj = NJ;
  int nk = NK;
  int nl = NL;

  /* Variable declaration/allocation. */
  DATA_TYPE alpha;
  DATA_TYPE beta;
  POLYBENCH_2D_ARRAY_DECL(tmp,DATA_TYPE,NI,NJ,ni,nj);
  POLYBENCH_2D_ARRAY_DECL(A,DATA_TYPE,NI,NK,ni,nk);
  POLYBENCH_2D_ARRAY_DECL(B,DATA_TYPE,NK,NJ,nk,nj);
  POLYBENCH_2D_ARRAY_DECL(C,DATA_TYPE,NJ,NL,nj,nl);
  POLYBENCH_2D_ARRAY_DECL(D,DATA_TYPE,NI,NL,ni,nl);

  /* Initialize array(s). */
  init_array (ni, nj, nk, nl, &alpha, &beta,
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Start timer. */
  polybench_start_instruments;

  /* Run kernel. */
  kernel_2mm (ni, nj, nk, nl,
	      alpha, beta,
	      POLYBENCH_ARRAY(tmp),
	      POLYBENCH_ARRAY(A),
	      POLYBENCH_ARRAY(B),
	      POLYBENCH_ARRAY(C),
	      POLYBENCH_ARRAY(D));

  /* Stop and print timer. */
  polybench_stop_instruments;
  polybench_print_instruments;

  /* Prevent dead-code elimination. All live-out data must be printed
     by the function call in argument. */
  polybench_prevent_dce(print_array(ni, nl,  POLYBENCH_ARRAY(D)));

  /* Be clean. */
  POLYBENCH_FREE_ARRAY(tmp);
  POLYBENCH_FREE_ARRAY(A);
  POLYBENCH_FREE_ARRAY(B);
  POLYBENCH_FREE_ARRAY(C);
  POLYBENCH_FREE_ARRAY(D);

  return 0;
}

