/* Tunable blocking factors for the main kernel.
   They can be overridden at compile time (e.g., -DTILE_I=64). */
#ifndef TILE_I
# define TILE_I 32
#endif
#ifndef TILE_J
# define TILE_J 32
#endif
#ifndef TILE_K
# define TILE_K 32
#endif
#ifndef TILE_L
# define TILE_L 32
#endif


/* Main computational kernel. The whole function will be timed,
   including the call and return. */
static
void kernel_2mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  int i, j, k, l;
  int ii, jj, kk, ll;

  /* Local copies of tile sizes (kept constant inside the SCoP). */
  const int tile_i = TILE_I;
  const int tile_j = TILE_J;
  const int tile_k = TILE_K;
  const int tile_l = TILE_L;

#pragma scop
  /* 1) Initialize tmp once.
     This is equivalent to the original per-(i,j) initialization done
     just before the k-reduction, but performed as a separate, dense
     pass over tmp. */
  for (i = 0; i < _PB_NI; ++i)
    for (j = 0; j < _PB_NJ; ++j)
      tmp[i][j] = SCALAR_VAL(0.0);

  /* 2) First GEMM: tmp = alpha * A * B
        Original math:
            tmp[i][j] = 0;
            for k: tmp[i][j] += alpha * A[i][k] * B[k][j];
        Optimized order with tiling:
          - outer tiling over i, k, j to improve cache reuse
          - inner-most loop over j for unit-stride access in B[k][j]
            and tmp[i][j]
          - alpha * A[i][k] hoisted out of the inner j-loop. */
  for (ii = 0; ii < _PB_NI; ii += tile_i) {
    int i_max = ii + tile_i;
    if (i_max > _PB_NI)
      i_max = _PB_NI;

    for (kk = 0; kk < _PB_NK; kk += tile_k) {
      int k_max = kk + tile_k;
      if (k_max > _PB_NK)
        k_max = _PB_NK;

      for (jj = 0; jj < _PB_NJ; jj += tile_j) {
        int j_max = jj + tile_j;
        if (j_max > _PB_NJ)
          j_max = _PB_NJ;

        for (i = ii; i < i_max; ++i) {
          for (k = kk; k < k_max; ++k) {
            /* Scalar kept in a register, reused across all j in this tile. */
            DATA_TYPE a_ik = alpha * A[i][k];

            DATA_TYPE * restrict tmp_ptr = &tmp[i][jj];
            DATA_TYPE * restrict b_ptr   = &B[k][jj];

            for (j = jj; j < j_max; ++j) {
              /* tmp[i][j] += alpha * A[i][k] * B[k][j]; */
              *tmp_ptr += a_ik * (*b_ptr);
              ++tmp_ptr;
              ++b_ptr;
            }
          }
        }
      }
    }
  }

  /* 3) Scale D by beta once per element, outside of the j-reduction.
        This is equivalent to the original D[i][l] *= beta performed
        immediately before the inner accumulation. */
  for (i = 0; i < _PB_NI; ++i)
    for (l = 0; l < _PB_NL; ++l)
      D[i][l] *= beta;

  /* 4) Second GEMM: D += tmp * C
        Original math:
            D[i][l] *= beta;
            for j: D[i][l] += tmp[i][j] * C[j][l];
        Optimized order with tiling:
          - loop order i–j–l so that l (columns of D/C) is innermost,
            giving unit-stride access in both C[j][l] and D[i][l]
          - tiling over i, j, l to improve cache locality
          - tmp[i][j] hoisted out of the inner l-loop. */
  for (ii = 0; ii < _PB_NI; ii += tile_i) {
    int i_max = ii + tile_i;
    if (i_max > _PB_NI)
      i_max = _PB_NI;

    for (jj = 0; jj < _PB_NJ; jj += tile_j) {
      int j_max = jj + tile_j;
      if (j_max > _PB_NJ)
        j_max = _PB_NJ;

      for (ll = 0; ll < _PB_NL; ll += tile_l) {
        int l_max = ll + tile_l;
        if (l_max > _PB_NL)
          l_max = _PB_NL;

        for (i = ii; i < i_max; ++i) {
          for (j = jj; j < j_max; ++j) {
            DATA_TYPE t_ij = tmp[i][j];

            DATA_TYPE * restrict d_ptr = &D[i][ll];
            DATA_TYPE * restrict c_ptr = &C[j][ll];

            for (l = ll; l < l_max; ++l) {
              /* D[i][l] += tmp[i][j] * C[j][l]; */
              *d_ptr += t_ij * (*c_ptr);
              ++d_ptr;
              ++c_ptr;
            }
          }
        }
      }
    }
  }
#pragma endscop

}


int main(int argc, char** argv)
{
