static
void kernel_2mm[[gnu::flatten, gnu::noinline]](int ni, int nj, int nk, int nl,
		DATA_TYPE alpha,
		DATA_TYPE beta,
		DATA_TYPE POLYBENCH_2D(tmp,NI,NJ,ni,nj),
		DATA_TYPE POLYBENCH_2D(A,NI,NK,ni,nk),
		DATA_TYPE POLYBENCH_2D(B,NK,NJ,nk,nj),
		DATA_TYPE POLYBENCH_2D(C,NJ,NL,nj,nl),
		DATA_TYPE POLYBENCH_2D(D,NI,NL,ni,nl))
{
  /* Use local restrict-qualified views to help the compiler with
     alias analysis and vectorization. */
  DATA_TYPE (* __restrict tmp_)[nj] = tmp;
  DATA_TYPE (* __restrict A_)[nk]   = A;
  DATA_TYPE (* __restrict B_)[nj]   = B;
  DATA_TYPE (* __restrict C_)[nl]   = C;
  DATA_TYPE (* __restrict D_)[nl]   = D;

  int i, j, k;
  int ii, jj, kk, ll;
  int i_end, j_end, k_end, l_end;

  /* Tunable tile sizes. These are chosen so that the working tiles of
     A/B/tmp and tmp/C/D fit comfortably in L1/L2 cache on a modern x64 CPU.
     Each tile touches at most TI*TJ + TJ*TK + TI*TL elements at a time. */
  const int TI = 32; /* tile size in i  (rows of A, tmp, D) */
  const int TJ = 32; /* tile size in j  (cols of tmp/B, rows of C) */
  const int TK = 32; /* tile size in k  (inner dimension of A/B)  */
  const int TL = 32; /* tile size in l  (cols of C/D)             */

  (void)ni; (void)nj; (void)nk; (void)nl; /* silence unused warnings */

#pragma scop
  /* Compute: D := alpha * A * B * C + beta * D
   *
   * We keep the two GEMM stages:
   *   tmp = alpha * A * B      (NI x NJ)
   *   D   = beta * D + tmp * C (NI x NL)
   *
   * but reorganize the loops for better cache locality and
   * unit-stride memory access, and block the iteration space.  The
   * reduction order over k (first GEMM) and over j (second GEMM) is
   * preserved for each element, so floating-point semantics match the
   * original code.
   */

  for (ii = 0; ii < _PB_NI; ii += TI)
  {
    i_end = ii + TI;
    if (i_end > _PB_NI) i_end = _PB_NI;

    /* ------------------------------------------------------------
     * Stage 1 for rows in [ii, i_end):
     *   tmp[i, j] = alpha * sum_k A[i, k] * B[k, j]
     *
     * Loop order inside tiles: i – k – j, with j innermost to get
     * unit-stride access in both B[k, j] and tmp[i, j].
     * ------------------------------------------------------------ */
    for (jj = 0; jj < _PB_NJ; jj += TJ)
    {
      j_end = jj + TJ;
      if (j_end > _PB_NJ) j_end = _PB_NJ;

      /* Initialize tmp tile to zero once before accumulating over k. */
      for (i = ii; i < i_end; ++i)
      {
        DATA_TYPE * __restrict tmp_row = &tmp_[i][jj];
        for (j = jj; j < j_end; ++j)
          tmp_row[j - jj] = SCALAR_VAL(0.0);
      }

      /* Accumulate alpha * A * B into tmp tile, blocked in k. */
      for (kk = 0; kk < _PB_NK; kk += TK)
      {
        k_end = kk + TK;
        if (k_end > _PB_NK) k_end = _PB_NK;

        for (i = ii; i < i_end; ++i)
        {
          DATA_TYPE * __restrict tmp_row = &tmp_[i][jj];

          for (k = kk; k < k_end; ++k)
          {
            const DATA_TYPE a_ik = alpha * A_[i][k];
            const DATA_TYPE * __restrict b_row = &B_[k][jj];

            /* Innermost loop over j has unit-stride accesses to
               both tmp_row and b_row, enabling efficient SIMD. */
            for (j = jj; j < j_end; ++j)
              tmp_row[j - jj] += a_ik * b_row[j - jj];
          }
        }
      }
    }

    /* ------------------------------------------------------------
     * Stage 2 for the same rows in [ii, i_end):
     *   D[i, l] = beta * D[i, l] + sum_j tmp[i, j] * C[j, l]
     *
     * Loop order inside tiles: i – j – l, with l innermost to get
     * unit-stride access in both C[j, l] and D[i, l].
     * ------------------------------------------------------------ */
    for (ll = 0; ll < _PB_NL; ll += TL)
    {
      l_end = ll + TL;
      if (l_end > _PB_NL) l_end = _PB_NL;

      /* Scale D tile by beta once. */
      for (i = ii; i < i_end; ++i)
      {
        DATA_TYPE * __restrict d_row = &D_[i][ll];
        for (int l = ll; l < l_end; ++l)
          d_row[l - ll] *= beta;
      }

      /* Add tmp * C into D tile. */
      for (jj = 0; jj < _PB_NJ; jj += TJ)
      {
        j_end = jj + TJ;
        if (j_end > _PB_NJ) j_end = _PB_NJ;

        for (i = ii; i < i_end; ++i)
        {
          DATA_TYPE * __restrict d_row = &D_[i][ll];

          for (j = jj; j < j_end; ++j)
          {
            const DATA_TYPE t_ij = tmp_[i][j];
            const DATA_TYPE * __restrict c_row = &C_[j][ll];

            /* Innermost loop over l has unit-stride accesses to
               both d_row and c_row, enabling efficient SIMD. */
            for (int l = ll; l < l_end; ++l)
              d_row[l - ll] += t_ij * c_row[l - ll];
          }
        }
      }
    }
  }
