   *      Within the (i, j) loop we hoist tmp[i][j] into a scalar.
   *   This preserves the original accumulation order over j for each
   *   element of D while greatly improving memory locality.
   * ------------------------------------------------------------------ */

  /* 1) Scale D by beta (row-major, contiguous). */
  for (i = 0; i < _PB_NI; i++)
    for (l = 0; l < _PB_NL; l++)
      D[i][l] *= beta;

  /* 2) Blocked matrix multiplication for D += tmp * C. */
  for (ii = 0; ii < _PB_NI; ii += TI) {
    int i_max = (ii + TI < _PB_NI) ? (ii + TI) : _PB_NI;
    for (jj = 0; jj < _PB_NJ; jj += TJ) {
      int j_max = (jj + TJ < _PB_NJ) ? (jj + TJ) : _PB_NJ;
      for (ll = 0; ll < _PB_NL; ll += TL) {
        int l_max = (ll + TL < _PB_NL) ? (ll + TL) : _PB_NL;

        for (i = ii; i < i_max; ++i) {
          for (j = jj; j < j_max; ++j) {
            /* Hoist tmp[i][j] for reuse across l. */
            DATA_TYPE t_ij = tmp[i][j];

            /* Inner loop over contiguous l: D[i][l] and C[j][l]
               are both row-major, so this is unit-stride and
               well-suited for SIMD. */
            for (l = ll; l < l_max; ++l) {
              D[i][l] += t_ij * C[j][l];
            }
          }
        }

      }
    }
  }
#pragma endscop

}


